def find_Max_Num(digits):
    if not digits:
        return 0
    return int(''.join(map(str, sorted(digits, reverse=True))))

assert find_Max_Num([1,2,3]) == 321
print(find_Max_Num([1,2,3]))
print(find_Max_Num([0,0,0]))
print(find_Max_Num([9,0,1,5]))

