def pos_count(numbers):
    return sum(1 for number in numbers if number > 0)

assert pos_count([1, -2, 3, -4]) == 2
print(pos_count([1, -2, 3, -4]))

def is_samepatterns(colors, patterns):
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_to_color = {}

    for color, pattern in zip(colors, patterns):
        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        else:
            color_to_pattern[color] = pattern

        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            pattern_to_color[pattern] = color

    return True

assert is_samepatterns(["red","green","green"], ["a", "b", "b"]) == True
assert is_samepatterns(["red","green","greenn"], ["a","b","b"]) == False
assert is_samepatterns(["red","green","green"], ["a","b","c"]) == False
print("ok")

def find_substring(strings, substring):
    return any(substring in s for s in strings)

assert find_substring(["red", "black", "white", "green", "orange"], "ack") == True
